  builder_.add_PROVENANCE(PROVENANCE);
  builder_.add_TLE_LINES(TLE_LINES);
  builder_.add_POLYNOMIAL_EPHEMERIS(POLYNOMIAL_EPHEMERIS);
  builder_.add_COMPREHENSIVE_ORBIT(COMPREHENSIVE_ORBIT);
  builder_.add_EPHEMERIS(EPHEMERIS);
  builder_.add_MEAN_ELEMENTS(MEAN_ELEMENTS);
  builder_.add_PROPAGATOR_PORT_ID(PROPAGATOR_PORT_ID);
  builder_.add_SOURCE_HANDLE(SOURCE_HANDLE);
  builder_.add_INSTANCE(INSTANCE);
  builder_.add_NORAD_CATALOG_ID(NORAD_CATALOG_ID);
  builder_.add_OBJECT_NAME(OBJECT_NAME);
  builder_.add_OBJECT_ID(OBJECT_ID);
  builder_.add_HAS_HARD_BODY_RADIUS_M(HAS_HARD_BODY_RADIUS_M);
  builder_.add_HAS_APOGEE_ALTITUDE_M(HAS_APOGEE_ALTITUDE_M);
