inline ::flatbuffers::Offset<CQRCatalogRequest> CreateCQRCatalogRequest(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<CQRObjectSource>>> PRIMARIES = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<CQRObjectSource>>> SECONDARIES = 0,
    ::flatbuffers::Offset<CQRScreeningControls> CONTROLS = 0,
    ::flatbuffers::Offset<RFMCoordinateSystem> EVALUATION_FRAME = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint32_t>> ORDERED_CATALOG_INDICES = 0,
    uint32_t START_ORDER_INDEX = 0,
    bool HAS_START_ORDER_INDEX = false,
    uint32_t END_ORDER_INDEX = 0,
    bool HAS_END_ORDER_INDEX = false,
    uint32_t SECONDARY_START_ORDER_INDEX = 0,
    bool HAS_SECONDARY_START_ORDER_INDEX = false,
    uint32_t SECONDARY_END_ORDER_INDEX = 0,
    bool HAS_SECONDARY_END_ORDER_INDEX = false,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<CQRSourceProvenance>>> SELECTED_SOURCES = 0) {
  CQRCatalogRequestBuilder builder_(_fbb);
  builder_.add_SELECTED_SOURCES(SELECTED_SOURCES);
  builder_.add_SECONDARY_END_ORDER_INDEX(SECONDARY_END_ORDER_INDEX);
  builder_.add_SECONDARY_START_ORDER_INDEX(SECONDARY_START_ORDER_INDEX);
  builder_.add_END_ORDER_INDEX(END_ORDER_INDEX);
  builder_.add_START_ORDER_INDEX(START_ORDER_INDEX);
  builder_.add_ORDERED_CATALOG_INDICES(ORDERED_CATALOG_INDICES);
  builder_.add_EVALUATION_FRAME(EVALUATION_FRAME);
  builder_.add_CONTROLS(CONTROLS);
  builder_.add_SECONDARIES(SECONDARIES);
  builder_.add_PRIMARIES(PRIMARIES);
  builder_.add_HAS_SECONDARY_END_ORDER_INDEX(HAS_SECONDARY_END_ORDER_INDEX);
  builder_.add_HAS_SECONDARY_START_ORDER_INDEX(HAS_SECONDARY_START_ORDER_INDEX);
  builder_.add_HAS_END_ORDER_INDEX(HAS_END_ORDER_INDEX);
  builder_.add_HAS_START_ORDER_INDEX(HAS_START_ORDER_INDEX);
  return builder_.Finish();
}

inline ::flatbuffers::Offset<CQRCatalogRequest> CreateCQRCatalogRequestDirect(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    const std::vector<::flatbuffers::Offset<CQRObjectSource>> *PRIMARIES = nullptr,
    const std::vector<::flatbuffers::Offset<CQRObjectSource>> *SECONDARIES = nullptr,
    ::flatbuffers::Offset<CQRScreeningControls> CONTROLS = 0,
    ::flatbuffers::Offset<RFMCoordinateSystem> EVALUATION_FRAME = 0,
    const std::vector<uint32_t> *ORDERED_CATALOG_INDICES = nullptr,
    uint32_t START_ORDER_INDEX = 0,
    bool HAS_START_ORDER_INDEX = false,
    uint32_t END_ORDER_INDEX = 0,
    bool HAS_END_ORDER_INDEX = false,
    uint32_t SECONDARY_START_ORDER_INDEX = 0,
    bool HAS_SECONDARY_START_ORDER_INDEX = false,
    uint32_t SECONDARY_END_ORDER_INDEX = 0,
    bool HAS_SECONDARY_END_ORDER_INDEX = false,
    const std::vector<::flatbuffers::Offset<CQRSourceProvenance>> *SELECTED_SOURCES = nullptr) {
  auto PRIMARIES__ = PRIMARIES ? _fbb.CreateVector<::flatbuffers::Offset<CQRObjectSource>>(*PRIMARIES) : 0;
  auto SECONDARIES__ = SECONDARIES ? _fbb.CreateVector<::flatbuffers::Offset<CQRObjectSource>>(*SECONDARIES) : 0;
  auto ORDERED_CATALOG_INDICES__ = ORDERED_CATALOG_INDICES ? _fbb.CreateVector<uint32_t>(*ORDERED_CATALOG_INDICES) : 0;
  auto SELECTED_SOURCES__ = SELECTED_SOURCES ? _fbb.CreateVector<::flatbuffers::Offset<CQRSourceProvenance>>(*SELECTED_SOURCES) : 0;
  return CreateCQRCatalogRequest(
      _fbb,
      PRIMARIES__,
      SECONDARIES__,
      CONTROLS,
      EVALUATION_FRAME,
      ORDERED_CATALOG_INDICES__,
      START_ORDER_INDEX,
      HAS_START_ORDER_INDEX,
      END_ORDER_INDEX,
      HAS_END_ORDER_INDEX,
      SECONDARY_START_ORDER_INDEX,
      HAS_SECONDARY_START_ORDER_INDEX,
      SECONDARY_END_ORDER_INDEX,
      HAS_SECONDARY_END_ORDER_INDEX,
      SELECTED_SOURCES__);
}

