  auto OBJECT_IDS__ = OBJECT_IDS ? _fbb.CreateVector<::flatbuffers::Offset<::flatbuffers::String>>(*OBJECT_IDS) : 0;
  auto SEGMENT_IDS__ = SEGMENT_IDS ? _fbb.CreateVector<::flatbuffers::Offset<::flatbuffers::String>>(*SEGMENT_IDS) : 0;
